<script setup lang="ts">
import { computed, ref } from 'vue'
import BackendPanel from './components/BackendPanel.vue'
import FeatureMap from './components/FeatureMap.vue'
import backpackImage from './assets/backpacks.png'
type Customer={name:string;country:string;person:string;email:string;stage:string;score:number;product:string}
const extraPages=['功能思维导图','协作指挥中心','产品知识库','客户挖掘中心','询盘与商机','数据分析','系统设置']
const leadStatus=ref<Record<string,string>>({})
const products=ref([{name:'轻量商务拉杆箱',spec:'PC 材质 · 20 / 24 / 28 寸',moq:'300 件',delivery:'35–45 天'},{name:'城市通勤双肩包',spec:'防泼水面料 · 15.6 寸电脑仓',moq:'500 件',delivery:'30–40 天'},{name:'户外旅行袋',spec:'耐磨涤纶 · 40L / 60L',moq:'300 件',delivery:'30–45 天'}])
const mining=ref(false),market=ref('德国'),kind=ref('品牌商 / 批发商'),keyword=ref('luggage / suitcase'),activeLead=ref('')
function reviewLead(name:string){leadStatus.value[name]='已入库';if(!customers.value.some(c=>c.name===name)){customers.value.push({name,country:market.value,person:'待核实',email:'',stage:'待联系',score:86,product:keyword.value});persist()}notice.value='线索已审核并导入 CRM'}
const page=ref('工作台'),search=ref(''),filter=ref('全部阶段'),notice=ref(''),modal=ref(false)
const customers=ref<Customer[]>(JSON.parse(localStorage.getItem('yt-customers')||'null')||[
{name:'Nordic Travel Co.',country:'🇩🇪 德国',person:'Anna Schmidt',email:'anna@nordic.example',stage:'重点跟进',score:96,product:'商务拉杆箱'},
{name:'Urban Carry Studio',country:'🇺🇸 美国',person:'Michael Johnson',email:'michael@urban.example',stage:'已发报价',score:92,product:'城市通勤背包'},
{name:'Voyage Maison',country:'🇫🇷 法国',person:'Claire Martin',email:'claire@voyage.example',stage:'初步接洽',score:88,product:'轻量旅行箱'},
{name:'Pacific Outdoor',country:'🇦🇺 澳大利亚',person:'James Wilson',email:'james@pacific.example',stage:'待联系',score:85,product:'户外旅行包'},
{name:'Tokyo Lifestyle',country:'🇯🇵 日本',person:'Yuki Tanaka',email:'yuki@tokyo.example',stage:'重点跟进',score:91,product:'休闲双肩包'},
{name:'Atlas Retail Group',country:'🇬🇧 英国',person:'Oliver Brown',email:'oliver@atlas.example',stage:'待联系',score:83,product:'ABS 拉杆箱'}])
const visible=computed(()=>customers.value.filter(c=>(c.name+c.country+c.person).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='全部阶段'||c.stage===filter.value)))
const tasks=ref([{name:'欧洲箱包采购商挖掘',desc:'德国 · 法国 · 荷兰 / 旅行箱、商务箱',status:'运行中',progress:68,count:128},{name:'北美品牌客户画像分析',desc:'美国 · 加拿大 / 通勤背包',status:'待启动',progress:0,count:0},{name:'高匹配客户开发信生成',desc:'基于客户画像生成个性化英文开发信',status:'已完成',progress:100,count:36}])
const logs=ref(JSON.parse(localStorage.getItem('yt-logs')||'[]') as string[]),note=ref(''),selected=ref('Nordic Travel Co.'),draft=ref(''),form=ref({name:'',country:'',person:'',email:'',product:''})
function persist(){localStorage.setItem('yt-customers',JSON.stringify(customers.value))}
function add(){if(!form.value.name.trim())return;customers.value.unshift({...form.value,stage:'待联系',score:80});persist();modal.value=false;form.value={name:'',country:'',person:'',email:'',product:''};notice.value='客户已保存到本机'}
function saveNote(){if(!note.value.trim())return;logs.value.unshift(`${selected.value}｜${note.value}｜${new Date().toLocaleString('zh-CN')}`);localStorage.setItem('yt-logs',JSON.stringify(logs.value));note.value='';notice.value='跟进记录已保存'}
function copyDraft(){navigator.clipboard.writeText(draft.value).then(()=>notice.value='开发信已复制').catch(()=>notice.value='复制不可用，请手动复制草稿')}
function generate(){draft.value=`Subject: Travel bag collection for ${selected.value}\n\nHi there,\n\nI'm from Yuetuo Bags. We specialize in quality luggage and travel bags with flexible OEM/ODM options. We'd love to explore a collection tailored to your market.\n\nMay I share our latest catalog and sample options?\n\nBest regards,\nYuetuo Bags`;notice.value='已生成模拟开发信，可编辑复制'}
</script>

<template>
<div class="app"><aside><div class="brand"><b>Y</b><span>悦拓箱包<small>AI 外贸获客系统</small></span></div><div class="workspace">YUETUO WORKSPACE</div><nav><button v-for="(item,i) in ['工作台','客户 CRM','AI 任务中心','客户跟进中心']" :class="{active:page===item}" @click="page=item">{{['◈','▦','✧','☷'][i]}} <span>{{item}}</span><em v-if="i===1">{{customers.length}}</em></button><button v-for="(item,i) in extraPages" :class="{active:page===item}" @click="page=item">{{['⋈','✧','▤','⌕','◇','▥','⚙'][i]}} <span>{{item}}</span></button></nav><div class="side-bottom"><div class="ai-status">● 模拟数据模式<small>账号未连接 · 数据仅存本机</small></div><div class="avatar">悦 <span>悦拓管理员<small>团队工作空间 · V1.0</small></span></div></div></aside>
<main><header><span>工作空间 <i>/</i> <strong>{{page}}</strong></span><div><span class="demo">● 模拟数据</span><span class="header-avatar">悦</span></div></header><div class="content"><div class="page-heading" :class="{'home-hero':page==='工作台'}"><div><div class="eyebrow">YUETUO · GLOBAL GROWTH</div><h1>{{page==='工作台'?'让好产品，遇见全球好客户':page}}</h1><p>{{page==='工作台'?'早上好，悦拓团队。今天也有新的生意机会等你发现。':'从发现到成交，让每一次客户连接更有价值。'}}</p></div><div class="heading-actions"><button v-if="page==='工作台'" class="primary" @click="page='客户挖掘中心'">开始挖掘客户 →</button><button v-else class="primary" @click="modal=true">＋ 新增客户</button></div><img v-if="page==='工作台'" class="hero-backpacks" :src="backpackImage" alt="悦拓粉彩拼色书包"/></div>
<div v-if="notice" class="notice" @click="notice=''">✓ {{notice}} <span>×</span></div>
<template v-if="page==='工作台'"><div class="stats"><article v-for="(s,i) in [['客户总数',customers.length,'本机客户资产'],['高匹配客户',customers.filter(c=>c.score>=90).length,'匹配评分 ≥ 90'],['进行中任务',tasks.filter(t=>t.status==='运行中').length,'自动探索新机会'],['跟进记录',logs.length,'持续积累客户关系']]" ><div>{{s[0]}} <span>{{['◎','↗','✧','☷'][i]}}</span></div><strong>{{s[1]}}</strong><small>{{s[2]}}</small></article></div><div class="dashboard-grid"><section class="panel collaboration"><div class="section-title"><h2>✧ AI 协作动态</h2><button @click="page='协作指挥中心'">查看全部 →</button></div><div class="agent-activity" v-for="(t,i) in tasks"><span class="activity-icon">{{['⌕','✉','☷'][i]}}</span><div class="activity-copy"><b>{{t.name}}</b><p>{{t.desc}}</p></div><div class="activity-progress"><span>{{t.status}} · {{t.progress}}%</span><div class="progress"><i :style="{width:t.progress+'%'}"></i></div></div></div><div class="tip">演示任务 · 真实执行引擎尚未接入</div></section><section class="panel"><div class="section-title"><h2>今日行动</h2><span class="muted">保持连接，推动成交</span></div><div class="action" v-for="(x,i) in ['跟进 Nordic Travel 报价反馈','为 Urban Carry 准备产品目录','探索欧洲旅行箱采购商']"><span class="action-icon">{{['↗','▤','✧'][i]}}</span><div><b>{{x}}</b><small>{{['重点客户 · 建议今日联系','已发报价 · 产品资料','AI 获客 · 新市场机会'][i]}}</small></div><button @click="page=i===2?'AI 任务中心':'客户跟进中心'">→</button></div><div class="tip">✧ 小提示：个性化跟进，让客户更愿意回复。</div></section></div></template>
<section v-if="page==='客户 CRM'||page==='工作台'" class="panel customer-panel"><div class="section-title"><div><h2>{{page==='工作台'?'重点客户':'客户资产库'}}</h2><p>集中管理全球客户，把握每一个合作机会</p></div><button v-if="page==='工作台'" @click="page='客户 CRM'">全部客户 →</button></div><div class="filters"><input v-model="search" placeholder="⌕ 搜索公司、联系人、国家"/><select v-model="filter"><option v-for="s in ['全部阶段','待联系','初步接洽','重点跟进','已发报价','已成交']">{{s}}</option></select><span class="muted">共 {{visible.length}} 位客户</span></div><div class="table-wrap"><table><thead><tr><th>客户 / 公司</th><th>国家 / 地区</th><th>关注产品</th><th>客户匹配度</th><th>客户阶段</th><th>操作</th></tr></thead><tbody><tr v-for="c in visible" :key="c.name"><td><b>{{c.name}}</b><small>{{c.person}}</small></td><td>{{c.country}}</td><td>{{c.product}}</td><td><span class="score">✧ {{c.score}}</span></td><td><select v-model="c.stage" @change="persist"><option v-for="s in ['待联系','初步接洽','重点跟进','已发报价','已成交']">{{s}}</option></select></td><td><button class="text-button" @click="selected=c.name;page='客户跟进中心'">跟进 ↗</button></td></tr></tbody></table><div v-if="!visible.length" class="empty">暂无匹配客户，请调整筛选条件</div></div></section>
<template v-if="page==='AI 任务中心'"><div class="banner"><div><h2>你的 AI 外贸工作伙伴</h2><p>发现客户、分析需求、撰写开发信，让团队专注有价值的沟通。</p></div><span>✧</span></div><div class="task-grid"><section class="panel task" v-for="t in tasks"><span class="tag">{{t.status}}</span><h2>{{t.name}}</h2><p>{{t.desc}}</p><div class="progress"><i :style="{width:t.progress+'%'}"></i></div><p>{{t.progress}}% <span class="right">发现 {{t.count}} 条模拟线索</span></p><button class="primary" @click="t.status=t.status==='运行中'?'已暂停':'运行中';notice='模拟任务状态已更新'">{{t.status==='运行中'?'暂停任务':'启动模拟任务'}}</button></section></div><p class="muted">演示任务不会访问外部平台或采集真实客户信息。</p></template>
<template v-if="page==='客户跟进中心'"><div class="follow-grid"><section class="panel"><h2>记录一次有价值的沟通</h2><label>选择客户<select v-model="selected"><option v-for="c in customers">{{c.name}}</option></select></label><label>跟进内容<textarea v-model="note" placeholder="记录客户需求、沟通结果和下一步计划…" rows="6"></textarea></label><button class="primary" @click="saveNote">保存跟进记录</button><h2 class="spaced">最近跟进</h2><p v-if="!logs.length" class="muted">还没有跟进记录，开始第一次沟通吧。</p><div class="log" v-for="log in logs">{{log}}</div></section><section class="panel"><div class="section-title"><h2>✧ AI 开发信助手</h2><span class="tag">模拟生成</span></div><p>根据当前客户，生成可编辑的英文开发信草稿。</p><button @click="generate">生成开发信</button><textarea v-model="draft" rows="14" placeholder="开发信草稿将显示在这里…"></textarea><button :disabled="!draft" @click="copyDraft">复制草稿</button><small class="muted">仅生成草稿，不会发送邮件。</small></section></div></template>
<template v-if="page==='产品知识库'"><div class="banner"><div><h2>让每一次开发，都有产品依据</h2><p>统一维护产品能力与企业资料，供客户匹配和开发信使用。</p></div><span>▤</span></div><div class="task-grid"><section class="panel" v-for="(p,i) in products"><div class="product-visual">{{['▣','▥','▰'][i]}}</div><span class="tag">OEM / ODM · 模拟资料</span><h2 class="spaced">{{p.name}}</h2><p>{{p.spec}}</p><div class="product-meta"><span>起订量<b>{{p.moq}}</b></span><span>参考交期<b>{{p.delivery}}</b></span></div><button @click="keyword=p.name;page='客户挖掘中心'">寻找匹配客户 →</button></section></div><section class="panel spaced"><h2>企业能力档案</h2><p>悦拓箱包 · 定制 Logo / 包装设计 / 样品开发 / 出货质检</p><div class="tip">以上为页面演示资料，实际价格、认证和生产能力待企业确认。</div></section></template>
<template v-if="page==='客户挖掘中心'"><div class="mining-layout"><section class="panel"><div class="section-title"><h2>配置获客任务</h2><span class="tag">模拟运行</span></div><label>目标国家<select v-model="market"><option>德国</option><option>美国</option><option>法国</option><option>澳大利亚</option></select></label><label>客户类型<select v-model="kind"><option>品牌商 / 批发商</option><option>进口商</option><option>连锁零售商</option></select></label><label>产品关键词<input v-model="keyword" placeholder="例如 luggage / suitcase"/></label><label>线索来源<select><option>企业官网 + 行业目录（模拟）</option><option>展会名录（模拟）</option></select></label><div class="tip">排除条件：箱包工厂、维修服务、物流公司。当前不会访问外部数据源。</div><button class="primary spaced" @click="mining=true;notice='模拟任务已完成，可审核下方演示线索'">✧ 开始模拟挖掘</button></section><div><section class="panel"><div class="section-title"><h2>从发现到有效客户</h2><span class="muted">{{mining?'模拟已完成':'等待开始'}}</span></div><div class="pipeline"><div v-for="(step,i) in ['检索企业','清洗去重','分析匹配','人工审核']"><b :class="{done:mining}">{{mining?'✓':i+1}}</b><span>{{step}}</span></div></div><div class="tip">{{mining?'发现 4 条 → 排除 1 条重复 → 3 条待审核。数量为演示流程数据。':'配置目标条件后，运行模拟任务查看完整线索审核流程。'}}</div></section><section class="panel spaced"><div class="section-title"><h2>待审核线索</h2><span class="tag">{{mining?'3 条演示线索':'暂无结果'}}</span></div><div v-if="!mining" class="empty">⌕<p>先设定目标，发现适合悦拓的采购企业</p></div><div v-else class="lead-row" v-for="(name,i) in ['Horizon Travel Goods','Evergreen Retail','Summit Bag Studio']"><div><b>{{name}}</b><p>{{market}} · {{kind}} · 匹配度 {{[91,86,82][i]}}<br/>采购需求待核实 · 联系方式待核实</p><span class="tag">{{leadStatus[name]||'待审核'}}</span></div><div><button @click="activeLead=activeLead===name?'':name">查看依据</button><button class="primary" :disabled="!!leadStatus[name]" @click="reviewLead(name)">{{leadStatus[name]?'已入库':'审核入库'}}</button></div><div v-if="activeLead===name" class="evidence"><b>演示证据详情</b><p>示例官网产品页包含旅行箱系列，客户类型与目标渠道相符。尚无明确采购公告，不能确认近期采购意向。</p><p>来源：模拟企业官网 · 路径 /collections/luggage<br/>匹配依据：产品相关 40/40，市场匹配 25/30，渠道匹配 26/30。<br/>待核实：公司主体、采购负责人、商务邮箱、实际采购计划。</p></div></div></section></div></div></template>
<template v-if="page==='询盘与商机'"><section class="panel"><div class="section-title"><div><h2>商机推进看板</h2><p>从需求确认到报价寄样，清晰记录下一步。</p></div><span class="tag">演示商机</span></div><div class="kanban"><div v-for="(stage,i) in ['需求确认','报价中','样品中','谈判中']"><h2>{{stage}} <span class="muted">1</span></h2><article><span class="tag">{{['旅行箱','通勤背包','旅行包','定制拉杆箱'][i]}}</span><h2 class="spaced">{{customers[i]?.name}}</h2><p>数量：{{[500,800,300,1000][i]}} 件<br/>材质 / 包装：待确认<br/>交付日期：待沟通</p><div class="tip">下一步：{{['确认规格与目标价','跟进报价反馈','确认样品反馈','确认付款与交期'][i]}}</div><button @click="selected=customers[i]?.name||'';page='客户跟进中心'">记录沟通 →</button></article></div></div></section></template>
<template v-if="page==='数据分析'"><div class="stats"><article v-for="stat in [['CRM 客户',customers.length],['已审核线索',Object.keys(leadStatus).length],['跟进记录',logs.length],['已成交客户',customers.filter(c=>c.stage==='已成交').length]]"><div>{{stat[0]}}</div><strong>{{stat[1]}}</strong><small>当前本机数据</small></article></div><section class="panel"><h2>客户阶段分布</h2><p>依据 CRM 当前阶段实时汇总</p><div class="chart-row" v-for="stage in ['待联系','初步接洽','重点跟进','已发报价','已成交']"><span>{{stage}}</span><div><i :style="{width:customers.filter(c=>c.stage===stage).length/Math.max(customers.length,1)*100+'%'}"></i></div><b>{{customers.filter(c=>c.stage===stage).length}}</b></div><div class="tip">真实渠道成本、发送与回复数据尚未接入，ROI 和触达转化率暂不计算。</div></section></template>
<template v-if="page==='系统设置'"><section class="panel"><h2>工作空间设置</h2><div class="setting-row"><div><b>悦拓箱包 · V1.0</b><p>中文界面 / 本机模拟环境</p></div><span class="tag">管理员</span></div><div class="setting-row" v-for="name in ['企业邮箱','WhatsApp Business','客户数据服务','ERP 系统']"><div><b>{{name}}</b><p>尚未配置账号与接口</p></div><span class="muted">未连接</span></div><div class="tip">客户与跟进记录保存在当前浏览器；模拟挖掘任务与演示商机用于页面体验。当前不发送邮件、不调用外部获客服务。</div></section></template>
<template v-if="page==='协作指挥中心'"><div class="banner"><div><h2>悦拓箱包 · AI 协作工作空间</h2><p>你制定目标与审批重要操作，AI 总经理协调专业 Agent，执行结果统一沉淀。</p></div><span>✧</span></div><section class="panel"><div class="orchestrator"><span class="tag">决策层 · 页面规划</span><h2 class="spaced">你：最终负责人</h2><p>制定经营目标 · 审批重要操作 · 查看业务结果</p></div><div class="flow-arrow">↓</div><div class="orchestrator green"><span class="tag">调度层 · 待接入执行引擎</span><h2 class="spaced">AI 总经理 / Orchestrator</h2><p>目标拆解 → 任务派发 → 结果验收 → 失败重试 → 跨 Agent 协作</p><div class="tip">任务预留：负责人、目标、输入资料、执行步骤、验收标准、审批状态、结果与日志。</div></div><div class="flow-arrow">↓</div><div class="agent-grid"><article v-for="a in [{name:'客户开发 Agent',desc:'寻找并验证采购商，审核后加入 CRM',status:'模拟流程可体验',target:'客户挖掘中心'},{name:'业务跟进 Agent',desc:'客户分类、开发信草稿、沟通记录与提醒',status:'基础页面可体验',target:'客户跟进中心'},{name:'店铺运营 Agent',desc:'Shopify / Shopee / TikTok Shop / Lazada，预留商品与店铺关联',status:'后续规划',target:''},{name:'短视频 Agent',desc:'脚本、素材、剪辑、版本管理与多平台发布',status:'后续规划',target:''},{name:'广告专家 Agent',desc:'广告素材、投放建议、预算审批与效果回传',status:'后续规划',target:''},{name:'数据分析 Agent',desc:'汇总获客效果、询盘质量、店铺和营销数据',status:'基础统计可体验',target:'数据分析'}]"><span class="tag">{{a.status}}</span><h2 class="spaced">{{a.name}}</h2><p>{{a.desc}}</p><button v-if="a.target" @click="page=a.target">进入工作区 →</button><span v-else class="muted">尚未接入账号与执行服务</span></article></div><div class="flow-arrow">↕</div><div class="orchestrator"><h2>共享数据与证据中心</h2><p>CRM · 产品知识 · 素材库 · 任务记录 · 审批记录 · 执行日志</p><div class="shared-links"><button @click="page='客户 CRM'">客户数据</button><button @click="page='产品知识库'">产品资料</button><button @click="page='AI 任务中心'">任务记录</button><button @click="page='系统设置'">集成设置</button></div></div></section><section class="panel spaced"><h2>后续审批节点</h2><p>对外发信、内容发布、广告预算变更、商品修改等操作，预留审批详情、批准 / 驳回和结果追踪页面。当前未实现真实审批与执行。</p></section></template><FeatureMap v-if="page==='功能思维导图'"/><BackendPanel v-if="page==='系统设置'"/><footer>悦拓箱包 AI 外贸获客系统 <span>V1.0 · 以连接，开启全球生意</span></footer></div></main>
<div v-if="modal" class="overlay" @click.self="modal=false"><form class="dialog" @submit.prevent="add"><div class="section-title"><h2>新增客户</h2><button type="button" @click="modal=false">×</button></div><label v-for="(label,key) in {name:'公司名称',country:'国家 / 地区',person:'联系人',email:'邮箱',product:'关注产品'}">{{label}}<input v-model="form[key]" :required="key==='name'" :type="key==='email'?'email':'text'"/></label><button class="primary" type="submit">保存客户</button></form></div></div>
</template>
